  /* ---------- سجل الأسئلة المحلولة (دائم، لا يُمسح بإغلاق التطبيق) ---------- */
  const SEEN_KEY = 'montasir_qa_seen';
  function h53(str){
    let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
    for(let i = 0; i < str.length; i++){
      const c = str.charCodeAt(i);
      h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
  }
  let seenSet = null;
  function loadSeen(){
    if(seenSet) return seenSet;
    try{ seenSet = new Set(JSON.parse(localStorage.getItem(SEEN_KEY) || '[]')); }catch(e){ seenSet = new Set(); }
    return seenSet;
  }
  function isSeen(it){ return loadSeen().has(h53(it[0])); }
  function markSeen(it){
    loadSeen().add(h53(it[0]));
    try{ localStorage.setItem(SEEN_KEY, JSON.stringify(Array.from(seenSet))); }catch(e){}
  }
  function resetSeen(){
    seenSet = new Set();
    try{ localStorage.removeItem(SEEN_KEY); }catch(e){}
  }
  function pickUnseen(cat){
    if(cat === 'mix'){
      const keys = F.shuffle(Object.keys(QA));
      for(let i = 0; i < keys.length; i++){ const r = pickUnseen(keys[i]); if(r) return r; }
      return null;
    }
    if(cat === 'math'){
      for(let t = 0; t < 80; t++){ const g = genMath(); if(!isSeen(g)) return g; }
    }
    const pool = QA[cat].list.filter(function(it){ return !isSeen(it); });
    if(pool.length) return pool[rnd(0, pool.length - 1)];
    return null;
  }
  function nextQ(cat){ return pickUnseen(cat); }
  function exhausted(root, back){
    root.innerHTML = '<div class="fun-result" style="text-align:center"><p style="font-size:calc(18px * var(--font-scale));font-weight:700;margin:0 0 8px">🎉 أنهيت كل أسئلة هذا المجال</p>'
      + '<p class="hint" style="margin:0">لن تتكرر أي أسئلة سبق أن أجبت عنها. جرّب مجالًا آخر أو أعد ضبط السجل.</p></div>'
      + '<div class="modal-actions"><button type="button" class="btn btn-ghost" id="qaBack">المجالات</button>'
      + '<button type="button" class="btn btn-primary" id="qaReset">إعادة ضبط السجل</button></div>';
    q(root,'#qaBack').addEventListener('click', back);
    q(root,'#qaReset').addEventListener('click', function(){ resetSeen(); back(); });
  }

  /* بنوك قابلة للتحديث أونلاين (تُستخدم في «أسئلة وأجوبة» و«منو الأذكى؟») */
  if(F.bank) Object.keys(QA).forEach(function(k){
    if(k === 'math' || !QA[k] || !Array.isArray(QA[k].list) || !QA[k].list.length) return;
    F.bank.register({id:'qa_' + k, topic:QA[k].label, list:function(){ return QA[k].list; }, add:function(it){ QA[k].list.push(it); }});
  });
  F.register({id:'qa', cat:'ai', name:'أسئلة وأجوبة ذكية', desc:'أسئلة لا تنتهي في كل المجالات', emoji:'🧠', c1:'#7b61d1', c2:'#4a3a94',
    render:function(root){
      function menu(){
        root.innerHTML = '<p class="hint" style="text-align:center;margin:0 0 12px">اختر مجالًا — الأسئلة لا تنتهي وتتجدد باستمرار حتى تضغط «إنهاء»</p>'
          + Object.keys(QA).map(function(k){ return '<button type="button" data-cat="'+k+'" style="'+optBtn+'">'+esc(QA[k].label)+'</button>'; }).join('')
          + '<button type="button" data-cat="mix" style="'+optBtn+'">🎲 مختلط من كل المجالات</button>'
          + '<p class="hint" style="text-align:center;margin:10px 0 0">الأسئلة التي أجبت عنها لا تظهر مرة أخرى أبدًا</p>';
        root.querySelectorAll('[data-cat]').forEach(function(b){ b.addEventListener('click', function(){ start(b.dataset.cat); }); });
      }
      function start(cat){
        let n = 0, answered = 0, score = 0, streak = 0, bestStreak = 0;
        function show(){
          const it = nextQ(cat); if(!it) return exhausted(root, menu); n++;
          const opts = F.shuffle([it[1]].concat(it[2]));
          root.innerHTML = '<div class="gm-stats"><span>سؤال <b>'+n+'</b></span><span>النقاط <b>'+score+'</b> / '+answered+'</span><span>🔥 تتابع <b>'+streak+'</b></span></div>'
            + '<p style="font-size:calc(16px * var(--font-scale));font-weight:700;line-height:1.7;margin:0 0 14px">'+esc(it[0])+'</p>'
            + opts.map(function(o){ return '<button type="button" data-o="'+esc(o)+'" style="'+optBtn+'">'+esc(o)+'</button>'; }).join('')
            + '<div id="qaFb"></div>'
            + '<div class="modal-actions"><button type="button" class="btn btn-ghost" id="qaStop">🏁 إنهاء وعرض النتيجة</button></div>';
          root.querySelectorAll('[data-o]').forEach(function(b){
            b.addEventListener('click', function(){
              const ok = b.dataset.o === it[1];
              markSeen(it);
              answered++;
              if(ok){ score++; streak++; if(streak > bestStreak) bestStreak = streak; } else { streak = 0; }
              root.querySelectorAll('[data-o]').forEach(function(x){
                x.disabled = true;
                if(x.dataset.o === it[1]) x.style.background = '#2f7d4f';
                else if(x === b) x.style.background = '#a3402f';
              });
              q(root,'#qaFb').innerHTML = '<div class="fun-result"><p class="fun-text" style="margin:0 0 6px;font-weight:700">'+(ok?'✅ إجابة صحيحة!':'❌ الإجابة الصحيحة: '+esc(it[1]))+'</p>'
                + '<p class="hint" style="margin:0">'+esc(it[3])+'</p></div>'
                + '<div class="modal-actions"><button type="button" class="btn btn-primary" id="qaNext">التالي ◀</button></div>';
              q(root,'#qaNext').addEventListener('click', show);
            });
          });
          q(root,'#qaStop').addEventListener('click', end);
        }
        function end(){
          const pct = answered ? Math.round(score/answered*100) : 0;
          const msg = !answered ? 'لم تجب عن أي سؤال بعد' : pct>=90?'ممتاز! معلوماتك رائعة 🌟':pct>=60?'جيد جدًا، واصل التقدم 👏':'لا بأس، جرّب مرة أخرى وستتحسن 💪';
          root.innerHTML = '<div class="fun-result" style="text-align:center"><p style="font-size:calc(34px * var(--font-scale));margin:0">'+score+' / '+answered+'</p><p class="hint" style="margin:6px 0 0">'+msg+' · أفضل تتابع: '+bestStreak+'</p></div>'
            + '<div class="modal-actions"><button type="button" class="btn btn-ghost" id="qaMenu">المجالات</button><button type="button" class="btn btn-primary" id="qaAgain">جولة جديدة</button></div>';
          q(root,'#qaMenu').addEventListener('click', menu);
          q(root,'#qaAgain').addEventListener('click', function(){ start(cat); });
        }
        show();
      }
      menu();
    }});

  /* ---------- 😂 ذكاء الضحك والمرح ---------- */
