  function offlineDoctor(text){
    const hits = OFF_DOC.filter(function(d){ return hasAny(text, d.k); }).slice(0, 2);
    const head = '📴 لا يوجد اتصال بالإنترنت الآن، فهذا إرشاد عام محدود وليس تشخيصًا.\n\n';
    if(!hits.length){
      return head + '**لم أتعرّف على العرض بدون إنترنت.**\nصِف الأعراض بكلمات بسيطة (مثل: صداع، حرارة، سعال، ألم بطن، إسهال...) أو اتصل بالإنترنت لأحلّل حالتك بتفصيل أكبر.\n\n**بشكل عام:** راقب الأعراض، اشرب السوائل، وارتح، وراجع الطبيب إن اشتدّت أو استمرت أكثر من يومين أو ظهرت علامات خطر.';
    }
    return head + hits.map(function(d){
      return '**' + d.n + '**\n• الأسباب الشائعة: ' + d.c + '\n• ما يفيد الآن: ' + d.h + '\n• راجع الطبيب أو الطوارئ إذا: ' + d.r;
    }).join('\n\n') + '\n\n**تذكير:** لا تتناول دواءً موصوفًا دون طبيب أو صيدلي، وراجع مختصًا للتأكد.';
  }

