  function thinkMake(cfg, n){
    const keys = cfg.cat === 'all' ? Object.keys(THINK) : [cfg.cat];
    let pool = []; keys.forEach(function(k){ THINK[k][1].forEach(function(x){ pool.push(x); }); });
    return shuf(pool).slice(0, n).map(function(x){
      const wr = x[2] ? x[2] : numWrong(x[1], 3).map(String);
      const series = /^[\d\s,؟]+$/.test(x[0]);
      return { html: series ? '<p class="gm-seq" style="font-size:calc(30px * var(--font-scale))">' + esc(x[0]) + '</p>' : '<p style="font-size:calc(17px * var(--font-scale));font-weight:700;line-height:1.9;margin:12px 0">' + esc(x[0]) + '</p>',
        opts:shuf([x[1]].concat(wr)), ans:x[1], rv:x[0] + ' ← ' + x[1], note:esc(x[3] || '') };
    });
  }
