      ,s:['مشى الزول البكان يملا البيت دفا وما مشى من القلب','الموت ما بوجع البمشي، بوجع البفضل يتذكّر','بشتاق ليك في كل تفصيلة صغيرة','كل ركن في البيت بحكي عنك','صعب الزول يتعوّد على غياب ما بيرجع','الزول الطيب ما بموت، أثرو بفضل في القلوب','مشيت وفضل دعاك بحرسني','الحبايب بمشوا وأسماءهم بتفضل في لسانا','للفقد صوت ما بسمعو إلا الجرّبو','كلما الحال يضيق أتذكّر إيد كانت بتطمّني','الذكرى بتحيّي البمشوا وبتوجع البفضلوا','ما في زول بشبهك وما في حاجة بعوّض غيابك','رحمة على أرواح سبقتنا وخلّت فينا الحنين','كبرنا وكبر اشتياقنا للبكبروا ما شافونا','أبكي عليك وبصبر لأنو الله أرحم بيك مننا','كل ما أمرّ على مكانك قلبي بقف']
